using UnityEngine;

/// <summary>
/// Reads SolarpunkCharacterController state and feeds the Animator on the Visual child.
/// Each action state is a 1D blend tree driven by FacingDir (float): 0=Down, 1=DownLeft,
/// 2=Left, 3=UpLeft, 4=Up. Right-side facing is handled by flipping the sprite and
/// mirroring the FacingDir value. Camera-relative: "Down" = toward the camera.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class FlynnAnimationDriver : MonoBehaviour, IPlayerVisual
{
    [SerializeField] private SolarpunkCharacterController _controller;
    [SerializeField] private Camera _camera;
    [Tooltip("The child Visual GameObject that holds the SpriteRenderer + Animator.")]
    [SerializeField] private Transform _visualRoot;
    [SerializeField, Range(0.1f, 5f)] private float _visualScale = 1f;

    [Header("Facing (sprite flip)")]
    [Tooltip("SpriteRenderer to flip. Auto-found on _visualRoot at Awake if left empty.")]
    [SerializeField] private SpriteRenderer _sprite;
    [Tooltip("Min horizontal speed before facing updates.")]
    [SerializeField, Range(0f, 1f)] private float _faceDeadzone = 0.05f;

    [Header("Visual Center (for throw origin & aim reticle)")]
    [Tooltip("Half the sprite's visible height in world units. Used to compute the billboard's visual centre for camera-corrected spawn/reticle positions.")]
    [SerializeField, Range(0f, 3f)] private float _spriteHalfHeight = 0.5f;

    // ── Cached references ──────────────────────────────────────────────────────

    private Animator _animator;

    // Held while idle so the blend tree doesn't snap back to Down on release.
    private int _lastFacingDir;
    private bool _lastFlipX;

    // ── Animator parameter hashes ─────────────────────────────────────────────

    private static readonly int SpeedHash       = Animator.StringToHash("Speed");
    private static readonly int IsGroundedHash  = Animator.StringToHash("IsGrounded");
    private static readonly int JumpHash        = Animator.StringToHash("Jump");
    private static readonly int SwingHash       = Animator.StringToHash("Swing");
    private static readonly int HoldHash        = Animator.StringToHash("Hold");
    private static readonly int ThrowHash       = Animator.StringToHash("Throw");
    private static readonly int ScanHash        = Animator.StringToHash("Scan");
    private static readonly int FacingDirHash   = Animator.StringToHash("FacingDir");

    // ── IPlayerVisual ─────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _visualRoot != null
            ? _visualRoot.position + _visualRoot.up * _spriteHalfHeight
            : transform.position;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking =>
        _animator != null &&
        (_animator.GetCurrentAnimatorStateInfo(0).IsName("Swing") ||
         (_animator.IsInTransition(0) &&
          _animator.GetNextAnimatorStateInfo(0).IsName("Swing")));

    public void TriggerAttack(int animIndex)
    {
        // Legacy tool-index attack stubbed — use TriggerSwing instead.
    }

    public void BeginChargePose(int animIndex)
    {
        // Legacy charge windup stubbed.
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        // Legacy charge scrub stubbed.
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        Debug.Log($"[Anim] Swing (animIndex={animIndex}, speed={animSpeed:F2}, facing={_lastFacingDir}, flip={_lastFlipX}, animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(SwingHash);
    }

    public void CancelSwing()
    {
        Debug.Log($"[Anim] CancelSwing → Idle (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.Play("Idle", 0, 0f);
    }

    /// <summary>No-op. Facing is now driven by camera-relative FacingDir + sprite flip in Update.</summary>
    public void FaceWorldDirection(Vector3 worldDir) { }

    // ── Frame-by-frame trigger API ────────────────────────────────────────────

    public void TriggerJump()
    {
        Debug.Log($"[Anim] Jump (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(JumpHash);
    }

    public void TriggerSwing()
    {
        Debug.Log($"[Anim] Swing (facing={_lastFacingDir}, flip={_lastFlipX}, animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(SwingHash);
    }

    public void SetHolding(bool holding)
    {
        Debug.Log($"[Anim] Hold = {holding} (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetBool(HoldHash, holding);
    }

    public void TriggerThrow()
    {
        Debug.Log($"[Anim] Throw (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ThrowHash);
    }

    public void TriggerScan()
    {
        Debug.Log($"[Anim] Scan (animator={(_animator != null ? "ok" : "NULL")})");
        if (_animator == null) return;
        _animator.SetTrigger(ScanHash);
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        // Get Animator from the Visual child (not self)
        if (_visualRoot != null)
        {
            _animator = _visualRoot.GetComponent<Animator>();
            if (_sprite == null) _sprite = _visualRoot.GetComponentInChildren<SpriteRenderer>();
            _visualRoot.localScale = Vector3.one * _visualScale;
        }
        if (_camera == null) _camera = Camera.main;
        Debug.Log($"[Anim] Awake — visualRoot={(_visualRoot != null ? _visualRoot.name : "NULL")}, animator={(_animator != null ? "ok" : "NULL")}, sprite={(_sprite != null ? _sprite.name : "NULL")}");
    }

    private void Update()
    {
        if (_animator == null || _controller == null) return;

        Vector3 velocity = _controller.MoveInput;
        Vector2 xz = new Vector2(velocity.x, velocity.z);

        // Feed Speed and IsGrounded for locomotion
        _animator.SetFloat(SpeedHash, xz.magnitude);
        _animator.SetBool(IsGroundedHash, _controller.IsGrounded);

        // ── Camera-relative facing direction ──────────────────────────────────
        // Down = toward camera, Up = away from camera, Left = screen-left
        if (_camera != null && xz.sqrMagnitude >= _faceDeadzone * _faceDeadzone)
        {
            Vector3 camFwd   = Vector3.ProjectOnPlane(_camera.transform.forward, Vector3.up).normalized;
            Vector3 camRight = Vector3.ProjectOnPlane(_camera.transform.right, Vector3.up).normalized;

            float intoScreen  = Vector3.Dot(velocity, camFwd);    // + = away from camera = Up
            float screenRight = Vector3.Dot(velocity, camRight);  // + = screen-right

            // Angle from Down (toward camera), counterclockwise = screen-left
            float angle = Mathf.Atan2(-screenRight, -intoScreen) * Mathf.Rad2Deg;
            if (angle < 0f) angle += 360f;

            // Right-side facing → flip sprite and mirror angle to left side
            bool flip = angle > 180f;
            if (flip) angle = 360f - angle;

            // 5 sectors: 0=Down, 1=DownLeft, 2=Left, 3=UpLeft, 4=Up
            int dir;
            if      (angle < 22.5f)  dir = 0; // Down
            else if (angle < 67.5f)  dir = 1; // DownLeft
            else if (angle < 112.5f) dir = 2; // Left
            else if (angle < 157.5f) dir = 3; // UpLeft
            else                     dir = 4; // Up

            // Base sprites face right — flip when facing screen-left
            bool flipLeft = !flip;
            _animator.SetFloat(FacingDirHash, dir);
            if (_sprite != null) _sprite.flipX = flipLeft;

            _lastFacingDir = dir;
            _lastFlipX = flipLeft;
        }
        else
        {
            // Hold last facing when idle
            _animator.SetFloat(FacingDirHash, _lastFacingDir);
            if (_sprite != null) _sprite.flipX = _lastFlipX;
        }
    }
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    /// <summary>Max distance from the player to a resource or pickup for it to count as interactable.</summary>
    [SerializeField] private float _interactionRange = 3f;

    /// <summary>Public access to the interaction range for other controllers.</summary>
    public float InteractionRange => _interactionRange;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    /// <summary>
    /// Unified hover result produced each frame. All consumers should read from this
    /// instead of the individual HoveredXxx properties (which are deprecated).
    /// </summary>
    public PlayerAimHoverResult HoverResult { get; private set; }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateHoveredGrabbable(hovered);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);

        // Build unified hover result
        BuildHoverResult(hasHit, point, hovered);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    private void UpdateHoveredGrabbable(GameObject hovered)
    {
        HoveredGrabbable = null;
        if (hovered == null) return;

        Grabbable g = hovered.GetComponentInParent<Grabbable>();
        if (g == null) return;

        // Range gate: must be within interaction range (or already held)
        if (g.IsHeld || Vector3.Distance(transform.position, g.transform.position) <= _interactionRange)
            HoveredGrabbable = g;
    }

    /// <summary>The Grabbable object the mouse ray is pointing at, or null.</summary>
    public Grabbable HoveredGrabbable { get; private set; }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;

    private void BuildHoverResult(bool hasHit, Vector3 point, GameObject hovered)
    {
        HoverResult = new PlayerAimHoverResult
        {
            HasTarget = hasHit || HoveredAnchor != null || HoveredPullable != null || HoveredGrabbable != null,
            WorldPoint = WorldAimPoint,
            WorldItem = HoveredKeyPickup,
            ResourceNode = HoveredResource,
            MeleeResource = MeleeResource,
            RopeAnchor = HoveredAnchor,
            RopePullable = HoveredPullable,
            ScanTarget = hovered != null ? Find<ScanTarget>(hovered) : null,
            Interactable = HoveredInteractable,
            Grabbable = HoveredGrabbable,
            GrapplePoint = HoveredGrapplePoint,
            InInteractionRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange,
            InMeleeRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _meleeRange,
            SwingAnimIndex = SwingAnimIndex,
        };
    }
}

using UnityEngine;

/// <summary>
/// The visual/animation surface the player's combat &amp; interaction controllers drive,
/// decoupled from how the body is actually rendered. Implemented by both the legacy
/// sprite-sheet driver (<see cref="FlynnAnimationDriver"/>) and the procedural cube-rig
/// driver (<see cref="ProceduralCharacterDriver"/>) so the same wrench/throw/rope/reticle
/// logic works against either body without edits.
///
/// Controllers resolve it via <c>GetComponent&lt;IPlayerVisual&gt;()</c> in Awake.
/// </summary>
public interface IPlayerVisual
{
    /// <summary>World-space "hand" / chest origin for thrown projectiles and the rope end.</summary>
    Vector3 VisualCenter { get; }

    /// <summary>VisualCenter projected to the character's foot Y (ground-plane indicators).</summary>
    Vector3 VisualGroundCenter { get; }

    /// <summary>True while an attack/swing is playing (gates re-triggering).</summary>
    bool IsAttacking { get; }

    /// <summary>Fire the attack pose for the given tool index (1=pick 2=axe 3=hammer 4=wrench).</summary>
    void TriggerAttack(int animIndex);

    /// <summary>Enter the windup hold for the given tool index.</summary>
    void BeginChargePose(int animIndex);

    /// <summary>Scrub the windup pose with charge fraction 0→1 (also live-swaps the tool).</summary>
    void UpdateChargePose(int animIndex, float charge01);

    /// <summary>Release the swing at the given playback speed (higher = faster follow-through).</summary>
    void ReleaseSwing(int animIndex, float animSpeed);

    /// <summary>Abort a windup and return to neutral.</summary>
    void CancelSwing();

    /// <summary>Orient the body toward a world-space XZ direction. Ignores Y; no-op on zero.</summary>
    void FaceWorldDirection(Vector3 worldDir);
}

using UnityEngine;

/// <summary>
/// Drives the procedural cube character rig (twin-stick). Replaces the sprite-sheet
/// <see cref="FlynnAnimationDriver"/> on the cube player while satisfying the same
/// <see cref="IPlayerVisual"/> contract, so wrench/throw/rope/reticle keep working.
///
/// Rig layout (assigned in the Inspector):
///   BodyRig  — yaws to follow the mouse aim point (torso + arms).
///   LegRig   — yaws to the movement direction when moving, blends back to body when idle.
///   FootL/R  — translated in an opposite-phase step cycle along LegRig's local forward.
///   ArmR     — pitched back on charge, swept forward on release (procedural swing pose).
///
/// Decoupling BodyRig (→ mouse) from LegRig (→ move) is what produces the twin-stick look:
/// the torso aims while the legs walk in the direction you actually travel.
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class ProceduralCharacterDriver : MonoBehaviour, IPlayerVisual
{
    [Header("Sources")]
    [SerializeField] private SolarpunkCharacterController _controller;

    [Header("Rig")]
    [Tooltip("Torso pivot. Yaws to face the mouse aim point. Holds the body cube + arms.")]
    [SerializeField] private Transform _bodyRig;
    [Tooltip("Leg pivot. Yaws to the movement direction; blends to body facing when idle.")]
    [SerializeField] private Transform _legRig;
    [SerializeField] private Transform _footL;
    [SerializeField] private Transform _footR;
    [Tooltip("Right arm, swept procedurally during a swing.")]
    [SerializeField] private Transform _armR;
    [Tooltip("Hand position used as the throw/rope origin (VisualCenter). Falls back to body centre.")]
    [SerializeField] private Transform _handSocket;

    [Header("Facing")]
    [Tooltip("Rest / idle facing in world space (default -Z = toward the camera / screen-down).")]
    [SerializeField] private Vector3 _restForward = Vector3.back;
    [Tooltip("How far the body turns toward the movement heading off the rest facing. " +
             "1 = face the move direction fully (up = away from camera); " +
             "lower softens it (0.5 → pure left/right leans ~45°). Idle always returns to rest.")]
    [SerializeField, Range(0f, 1f)] private float _leanFactor = 1f;
    [Tooltip("How fast the body/legs slerp toward their target facing (per second).")]
    [SerializeField] private float _turnSpeed = 14f;

    [Header("Step cycle")]
    [Tooltip("Stride length: how far each foot travels fore/aft from neutral (world units).")]
    [SerializeField] private float _stride = 0.12f;
    [Tooltip("Foot lift height at the top of a step (world units).")]
    [SerializeField] private float _stepLift = 0.06f;
    [Tooltip("Step cycles per second at full speed.")]
    [SerializeField] private float _stepFrequency = 2.2f;

    [Header("Visual centre")]
    [Tooltip("Used only when no hand socket is assigned: body-centre height above the root.")]
    [SerializeField] private float _visualHalfHeight = 0.4f;

    [Header("Swing pose")]
    [Tooltip("Arm pitch (deg, local X) at full windup charge.")]
    [SerializeField] private float _windupAngle = -70f;
    [Tooltip("Arm pitch (deg, local X) at the forward end of a swing.")]
    [SerializeField] private float _swingThroughAngle = 60f;
    [Tooltip("Seconds the release sweep takes.")]
    [SerializeField] private float _swingDuration = 0.25f;

    private const float MoveEpsilon = 0.05f;

    private enum SwingPhase { None, Charging, Releasing }
    private SwingPhase _swingPhase = SwingPhase.None;
    private float _chargePitch;       // current windup pitch while charging
    private float _swingTimer;        // counts down through the release sweep
    private Quaternion _armRest = Quaternion.identity;

    private Vector3 _footLRest;
    private Vector3 _footRRest;
    private float _stepPhase;
    private float _stepWeight;        // 0 idle → 1 moving, smoothed so feet settle

    // ── IPlayerVisual ───────────────────────────────────────────────────────────

    public Vector3 VisualCenter =>
        _handSocket != null ? _handSocket.position
                            : transform.position + Vector3.up * _visualHalfHeight;

    public Vector3 VisualGroundCenter =>
        new Vector3(VisualCenter.x, transform.position.y, VisualCenter.z);

    public bool IsAttacking => _swingPhase != SwingPhase.None;

    public void TriggerAttack(int animIndex)
    {
        // No charge: snap straight into a release sweep.
        if (_swingPhase == SwingPhase.None) ReleaseSwing(animIndex, 1f);
    }

    public void BeginChargePose(int animIndex)
    {
        _swingPhase = SwingPhase.Charging;
        _chargePitch = 0f;
    }

    public void UpdateChargePose(int animIndex, float charge01)
    {
        if (_swingPhase != SwingPhase.Charging) return;
        _chargePitch = Mathf.Lerp(0f, _windupAngle, Mathf.Clamp01(charge01));
    }

    public void ReleaseSwing(int animIndex, float animSpeed)
    {
        _swingPhase = SwingPhase.Releasing;
        // Higher animSpeed → shorter sweep (faster follow-through).
        _swingTimer = _swingDuration / Mathf.Max(0.05f, animSpeed);
    }

    public void CancelSwing()
    {
        _swingPhase = SwingPhase.None;
        _swingTimer = 0f;
        _chargePitch = 0f;
    }

    public void FaceWorldDirection(Vector3 worldDir)
    {
        // No-op: facing is fully movement-driven (lean-to-move). Kept for the IPlayerVisual
        // contract — the wrench/rope controllers still call it, but it must not fight the lean.
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private float _restYaw;

    private void Awake()
    {
        if (_controller == null) _controller = GetComponent<SolarpunkCharacterController>();
        Vector3 rest = _restForward; rest.y = 0f;
        if (rest.sqrMagnitude < 0.0001f) rest = Vector3.back;
        _restYaw = Quaternion.LookRotation(rest.normalized, Vector3.up).eulerAngles.y;
        if (_footL != null) _footLRest = _footL.localPosition;
        if (_footR != null) _footRRest = _footR.localPosition;
        if (_armR != null) _armRest = _armR.localRotation;
    }

    private void Update()
    {
        float dt = Time.deltaTime;
        UpdateBodyFacing(dt);
        UpdateLegFacing(dt);
        UpdateStepCycle(dt);
        UpdateSwingPose(dt);
    }

    // ── Rig logic ───────────────────────────────────────────────────────────────

    private void UpdateBodyFacing(float dt)
    {
        if (_bodyRig == null) return;

        Vector3 move = _controller.MoveInput;
        move.y = 0f;

        // Turn toward the movement heading in all directions (up = facing away from camera).
        // _leanFactor scales how much of the rest→move angular delta is applied; 1 = face the
        // move direction fully. Idle → rest facing.
        float targetYaw = _restYaw;
        if (move.sqrMagnitude > MoveEpsilon * MoveEpsilon)
        {
            float moveYaw = Quaternion.LookRotation(move.normalized, Vector3.up).eulerAngles.y;
            targetYaw = _restYaw + Mathf.DeltaAngle(_restYaw, moveYaw) * _leanFactor;
        }

        Quaternion target = Quaternion.Euler(0f, targetYaw, 0f);
        _bodyRig.rotation = Quaternion.Slerp(_bodyRig.rotation, target, _turnSpeed * dt);
    }

    private void UpdateLegFacing(float dt)
    {
        // Legs share the body facing; the step cycle runs along that shared forward.
        if (_legRig != null && _bodyRig != null) _legRig.rotation = _bodyRig.rotation;
    }

    private void UpdateStepCycle(float dt)
    {
        float speed01 = Mathf.Clamp01(_controller != null ? _controller.NormalizedSpeed : 0f);
        bool moving = speed01 > 0.05f;

        // Ease the step amplitude in/out so feet settle cleanly when stopping.
        _stepWeight = Mathf.MoveTowards(_stepWeight, moving ? 1f : 0f, dt * 6f);
        if (moving) _stepPhase += dt * _stepFrequency * Mathf.Lerp(0.4f, 1f, speed01) * Mathf.PI * 2f;

        float s = Mathf.Sin(_stepPhase) * _stepWeight;
        ApplyFoot(_footL, _footLRest, s);
        ApplyFoot(_footR, _footRRest, -s);
    }

    private void ApplyFoot(Transform foot, Vector3 rest, float phase)
    {
        if (foot == null) return;
        // phase ∈ [-1,1]: fore/aft along local Z, lift only on the forward (positive) half.
        foot.localPosition = rest
            + Vector3.forward * (phase * _stride)
            + Vector3.up * (Mathf.Max(0f, phase) * _stepLift);
    }

    private void UpdateSwingPose(float dt)
    {
        if (_armR == null) return;

        float pitch;
        switch (_swingPhase)
        {
            case SwingPhase.Charging:
                pitch = _chargePitch;
                break;
            case SwingPhase.Releasing:
                _swingTimer -= dt;
                float t = _swingDuration > 0f
                    ? 1f - Mathf.Clamp01(_swingTimer / (_swingDuration))
                    : 1f;
                // Sweep from the windup angle through to the follow-through angle.
                pitch = Mathf.Lerp(_windupAngle, _swingThroughAngle, t);
                if (_swingTimer <= 0f) _swingPhase = SwingPhase.None;
                break;
            default:
                pitch = 0f;
                break;
        }

        Quaternion target = _armRest * Quaternion.Euler(pitch, 0f, 0f);
        // Snap while actively swinging, ease back to rest when idle.
        _armR.localRotation = _swingPhase == SwingPhase.None
            ? Quaternion.Slerp(_armR.localRotation, target, 12f * dt)
            : target;
    }
}

using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;

/// <summary>
/// Editor utility that creates AnimationClips from sprite PNGs and wires an
/// AnimatorController for Flynn's 2.5D 9-state animation system.
/// Run via menu: Flynn → Setup Animations
/// </summary>
public static class FlynnAnimationSetup
{
    private const string AnimOut = "Assets/Flynn/Animations";
    private const float  Fps     = 12f;
    private const string SpBase  = "Assets/Flynn/Sprites/character_animations";

    // ── Entry point ──────────────────────────────────────────────────────────

    [MenuItem("Flynn/Setup Animations")]
    public static void Run()
    {
        if (!AssetDatabase.IsValidFolder(AnimOut))
            AssetDatabase.CreateFolder("Assets/Flynn", "Animations");

        var clips = BuildAllClips();
        BuildController(clips);

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log("[FlynnAnimationSetup] All done.");
    }

    // ── Placeholder diagonal clips (single sprite, decoupled from controller) ──
    //
    // 8-direction support adds FacingDir 3 = back-diagonal (NE/NW). Until real
    // diagonal animations exist, these clips just hold one frame. This menu creates
    // ONLY the clips and leaves Flynn_AnimatorController untouched — wire the
    // FacingDir==3 states/transitions by hand (or extend BuildController later).

    private const string NewCharDir = SpBase + "/New Character";

    // FacingDir → single placeholder sprite (8-direction via flipX for the L/R pair):
    //   0 front, 1 back, 2 side, 3 back-diagonal (NE/NW), 4 front-diagonal (SE/SW).
    private static readonly (string suffix, string sprite)[] PlaceholderDirs =
    {
        ("Front",    "character_front_orth.png"),
        ("Back",     "character_back_orth.png"),
        ("Side",     "character_right.png"),
        ("BackDiag", "character_45_back_orth.png"),
        ("FrontDiag","character_45_orth.png"),
    };

    /// <summary>
    /// Sets every locomotion clip (Idle/Run/Jump × 5 directions) to a SINGLE frame of the
    /// matching New Character sprite. Existing clips are rewritten in place (GUID preserved,
    /// so AnimatorController state references survive); missing ones are created. The
    /// AnimatorController is NOT touched — wire the FacingDir==3/4 diagonal states by hand.
    /// </summary>
    [MenuItem("Flynn/Set Placeholder Sprites (single frame)")]
    public static void SetPlaceholderSprites()
    {
        if (!AssetDatabase.IsValidFolder(AnimOut))
            AssetDatabase.CreateFolder("Assets/Flynn", "Animations");

        int ok = 0, total = 0;
        foreach (var (suffix, spriteFile) in PlaceholderDirs)
        {
            string spritePath = $"{NewCharDir}/{spriteFile}";
            foreach (var (prefix, loop) in new[] { ("Idle", true), ("Run", true), ("Jump", false) })
            {
                total++;
                if (SetSingleSpriteClip($"Flynn_{prefix}_{suffix}", spritePath, loop) != null) ok++;
            }
        }

        AssetDatabase.SaveAssets();
        AssetDatabase.Refresh();
        Debug.Log($"[FlynnAnimationSetup] Placeholder sprites set: {ok}/{total} clips. " +
                  "Controller untouched — wire FacingDir==3 (back-diag) & ==4 (front-diag) states manually.");
    }

    /// <summary>
    /// Forces a clip to a one-frame sprite animation. Loads the existing asset (preserving its
    /// GUID + controller references) or creates it if absent, then overwrites the m_Sprite curve.
    /// </summary>
    private static AnimationClip SetSingleSpriteClip(string clipName, string spritePath, bool loop)
    {
        var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(spritePath);
        if (sprite == null)
        {
            Debug.LogWarning($"[FlynnAnimationSetup] Sprite not found (imported as a Sprite?): {spritePath}");
            return null;
        }

        string outPath = $"{AnimOut}/{clipName}.anim";
        var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath);
        bool existed = clip != null;
        if (!existed) clip = new AnimationClip();
        clip.frameRate = Fps;

        var binding = new EditorCurveBinding
        {
            type         = typeof(SpriteRenderer),
            path         = "",
            propertyName = "m_Sprite"
        };
        // Single keyframe replaces any prior multi-frame curve for this binding.
        var keys = new[] { new ObjectReferenceKeyframe { time = 0f, value = sprite } };
        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        if (!existed) AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);

        Debug.Log($"[FlynnAnimationSetup] {(existed ? "Rewrote" : "Created")} '{clipName}' → {sprite.name} (1 frame, loop={loop}).");
        return clip;
    }

    // ── Clip creation ────────────────────────────────────────────────────────

    private static Dictionary<string, AnimationClip> BuildAllClips()
    {
        // (clipName, folder, looping)
        var defs = new (string name, string folder, bool loop)[]
        {
            ("Flynn_Idle_Front",  SpBase + "/positive/idel_02", true),
            ("Flynn_Run_Front",   SpBase + "/positive/run_01",  true),
            ("Flynn_Jump_Front",  SpBase + "/positive/jump_02", false),
            ("Flynn_Idle_Back",   SpBase + "/back/idel_01",     true),
            ("Flynn_Run_Back",    SpBase + "/back/run_01",      true),
            ("Flynn_Jump_Back",   SpBase + "/back/jump_01",     false),
            ("Flynn_Idle_Side",   SpBase + "/side/idel_03",     true),
            ("Flynn_Run_Side",    SpBase + "/side/run_03",      true),
            ("Flynn_Jump_Side",   SpBase + "/side/jump_03",     false),
            // ── Attack animations (one-shot, tool-specific) ──────────────
            ("Flynn_attack_01",   SpBase + "/attack_01",        false),  // pick
            ("Flynn_attack_02",   SpBase + "/attack_02",        false),  // axe
            ("Flynn_attack_03",   SpBase + "/attack_03",        false),  // hammer
            ("Flynn_attack_04",   SpBase + "/attack_04",        false),  // wrench
        };

        var map = new Dictionary<string, AnimationClip>();
        foreach (var d in defs)
        {
            var clip = MakeClip(d.name, d.folder, d.loop);
            if (clip != null) map[d.name] = clip;
        }
        return map;
    }

    private static AnimationClip MakeClip(string clipName, string folder, bool loop)
    {
        // Convert asset-relative folder to filesystem path
        string dataPath = Application.dataPath.Replace('\\', '/'); // ends with /Assets
        string sysDir   = dataPath + "/" + folder.Substring("Assets/".Length);

        if (!Directory.Exists(sysDir))
        {
            Debug.LogWarning($"[FlynnAnimationSetup] Folder not found: {sysDir}");
            return null;
        }

        var pngPaths = Directory.GetFiles(sysDir, "*.png")
                                .Select(p => p.Replace('\\', '/'))
                                .OrderBy(Path.GetFileName)
                                .ToArray();

        var sprites = new List<Sprite>(pngPaths.Length);
        foreach (var full in pngPaths)
        {
            string assetPath = "Assets/" + full.Substring(dataPath.Length + 1);
            var sprite = AssetDatabase.LoadAssetAtPath<Sprite>(assetPath);
            if (sprite != null)
                sprites.Add(sprite);
            else
                Debug.LogWarning($"[FlynnAnimationSetup] Sprite not found at: {assetPath}");
        }

        if (sprites.Count == 0)
        {
            Debug.LogWarning($"[FlynnAnimationSetup] No sprites loaded for clip '{clipName}'");
            return null;
        }

        var clip = new AnimationClip { frameRate = Fps };

        var binding = new EditorCurveBinding
        {
            type         = typeof(SpriteRenderer),
            path         = "",
            propertyName = "m_Sprite"
        };

        var keys = new ObjectReferenceKeyframe[sprites.Count];
        for (int i = 0; i < sprites.Count; i++)
            keys[i] = new ObjectReferenceKeyframe { time = i / Fps, value = sprites[i] };

        AnimationUtility.SetObjectReferenceCurve(clip, binding, keys);

        // Loop settings
        var settings = AnimationUtility.GetAnimationClipSettings(clip);
        settings.loopTime = loop;
        AnimationUtility.SetAnimationClipSettings(clip, settings);
        clip.wrapMode = loop ? WrapMode.Loop : WrapMode.Once;

        // Save asset (replace if already exists)
        string outPath = $"{AnimOut}/{clipName}.anim";
        if (AssetDatabase.LoadAssetAtPath<AnimationClip>(outPath) != null)
            AssetDatabase.DeleteAsset(outPath);

        AssetDatabase.CreateAsset(clip, outPath);
        EditorUtility.SetDirty(clip);

        Debug.Log($"[FlynnAnimationSetup] Created '{clipName}'  ({sprites.Count} frames, loop={loop})");
        return clip;
    }

    // ── AnimatorController creation ──────────────────────────────────────────

    private static void BuildController(Dictionary<string, AnimationClip> clips)
    {
        string ctrlPath = $"{AnimOut}/Flynn_AnimatorController.controller";
        if (AssetDatabase.LoadAssetAtPath<AnimatorController>(ctrlPath) != null)
            AssetDatabase.DeleteAsset(ctrlPath);

        var ctrl = AnimatorController.CreateAnimatorControllerAtPath(ctrlPath);
        ctrl.AddParameter("Speed",       AnimatorControllerParameterType.Float);
        ctrl.AddParameter("IsGrounded",  AnimatorControllerParameterType.Bool);
        ctrl.AddParameter("FacingDir",   AnimatorControllerParameterType.Int);
        ctrl.AddParameter("Attack",      AnimatorControllerParameterType.Trigger);
        ctrl.AddParameter("AttackIndex", AnimatorControllerParameterType.Int);

        var sm = ctrl.layers[0].stateMachine;

        // Create states
        var idleFront = AddState(sm, clips, "Idle_Front", "Flynn_Idle_Front", new Vector3(300,    0, 0));
        var runFront  = AddState(sm, clips, "Run_Front",  "Flynn_Run_Front",  new Vector3(600,    0, 0));
        var jumpFront = AddState(sm, clips, "Jump_Front", "Flynn_Jump_Front", new Vector3(900,    0, 0));
